import pandas as pd

def analyze_subscription_conversion(user_activity: pd.DataFrame) -> pd.DataFrame:
    paid_users = set(user_activity[user_activity['activity_type'] == 'paid']['user_id'])
    filtered = user_activity[user_activity['user_id'].isin(paid_users)]
    if filtered.empty:
        return pd.DataFrame(columns=['user_id', 'trial_avg_duration', 'paid_avg_duration'])

    trial = filtered[filtered['activity_type'] == 'free_trial'].groupby('user_id')['activity_duration'].mean().round(2).reset_index()
    trial.rename(columns={'activity_duration': 'trial_avg_duration'}, inplace=True)

    paid = filtered[filtered['activity_type'] == 'paid'].groupby('user_id')['activity_duration'].mean().round(2).reset_index()
    paid.rename(columns={'activity_duration': 'paid_avg_duration'}, inplace=True)

    res = pd.DataFrame({'user_id': sorted(list(paid_users))})
    res = res.merge(trial, on='user_id', how='left').merge(paid, on='user_id', how='left')
    return res.sort_values(by='user_id')
